26	import { PostProcessingFactory } from './types';
27	
28	export const aggregationOperator: PostProcessingFactory<
29	  PostProcessingAggregation
30	> = (formData: QueryFormData, queryObject) => {
31	  const { aggregation = 'LAST_VALUE' } = formData;
32	
33	  if (aggregation === 'LAST_VALUE' || aggregation === 'raw') {
34	    return undefined;
35	  }
36	
37	  const metrics = ensureIsArray(queryObject.metrics);
38	  if (metrics.length === 0) {
39	    return undefined;
40	  }
41	
42	  const aggregates: Aggregates = {};
43	  metrics.forEach(metric => {
44	    const metricLabel = getMetricLabel(metric);
45	    aggregates[metricLabel] = {
46	      operator: aggregation,
47	      column: metricLabel,
48	    };
49	  });
50	
51	  return {
52	    operation: 'aggregate',
53	    options: {
54	      groupby: [],
55	      aggregates,
56	    },
57	  };
58	};
